// Match each inbound mail to an open outreach message by Gmail thread id first, then by sender address.
const mail = $('New inbox mail').first().json;
const open = $json.messages || [];
const from = String(mail.from?.value?.[0]?.address || mail.From || mail.from || '').toLowerCase();
const threadId = mail.threadId || '';
const subject = String(mail.subject || mail.Subject || '');
const text = String(mail.text || mail.snippet || '');
const isBounce = /mailer-daemon|postmaster/.test(from) || /delivery status notification|undeliverable|address not found/i.test(subject);
let match = open.find(m => threadId && m.thread_id && m.thread_id === threadId);
if (!match && !isBounce) match = open.find(m => (m.to_email || '').toLowerCase() === from);
if (!match && isBounce) {
  const addr = (text.match(/[\w.+-]+@[\w-]+\.[\w.-]+/g) || []).map(a => a.toLowerCase());
  match = open.find(m => addr.includes((m.to_email || '').toLowerCase()));
}
if (!match) return [];
return [{ json: {
  message_id: match.id,
  event: isBounce ? 'bounced' : 'replied',
  at: new Date().toISOString(),
  provider_message_id: mail.id || '',
  thread_id: threadId,
  detail: isBounce ? { bounce_reason: subject.slice(0, 200) } : { reply_snippet: text.slice(0, 300), sentiment: '' }
} }];
